    % Key points
    \filldraw[black] (0,1) circle (2pt) node[above] {$(0,1)$};
    \filldraw[black] (3.14,-1) circle (2pt) node[below] {$\pi$};
    \filldraw[black] (6.28,1) circle (2pt) node[above] {$2\pi$};
    \filldraw[black] (1.57,0) circle (2pt) node[below right] {$\frac{\pi}{2}$};
    \filldraw[black] (4.71,0) circle (2pt) node[below left] {$\frac{3\pi}{2}$};
