% Open circles at (1,1) and (1,2)
\addplot[mark=o, fill=white] coordinates {(1,1)};
\addplot[mark=o, fill=white] coordinates {(1,2)};

% Closed blue circle at (1,4)
\addplot[blue, mark=*] coordinates {(1,4)};

% Add labels to points
\node[above right] at (end1) {$(1,1)$};
\node[above left] at (start2) {$(1,2)$};
\node[above] at (1,4) {$(1,4)$};

\end{axis}
\end{tikzpicture}
\end{document}
```

