    \node[anchor=north] at (B) {B};
    \node[anchor=north] at (C) {C};

    % Draw interior angles with specified constraints
    \pic [draw, "$\alpha$", angle eccentricity=1.5, angle radius=0.5cm] {angle = B--A--C};
    \pic [draw, "$\beta$", angle eccentricity=1.5, angle radius=0.5cm] {angle = C--B--A};
    \pic [draw, "$\gamma$", angle eccentricity=1.5, angle radius=0.5cm] {angle = A--C--B};

    % Calculate side lengths
    \coordinate (AB) at ($(A)-(B)$);
    \coordinate (BC) at ($(B)-(C)$);
    \coordinate (CA) at ($(C)-(A)$);

    % Add grid for reference
    \draw[gray!30, dashed] (-4,-1) grid (6,5);
\end{tikzpicture}
\end{document}
```

